package main

import (
	"slices"
	"testing"
)

func TestTokens(t *testing.T) {
	tests := []struct {
		name, before, after string
		test, equal         bool
	}{
		{"line comment", "package p\n// old\nvar x = 1\n", "package p\n// new\nvar x = 1 // inline\n", false, true},
		{"block comment", "package p\n/* old */ var x = 1\n", "package p\n/* new\ncomment */ var x = 1\n", false, true},
		{"formatting", "package p\nvar x=1\n", "package p\n\nvar x = 1;\n", false, true},
		{"code", "package p\nvar x = 1\n", "package p\nvar x = 2\n", false, false},
		{"comment in string", "package p\nvar x = `// old`\n", "package p\nvar x = `// new`\n", false, false},
		{"block comment in string", "package p\nvar x = `/* old */`\n", "package p\nvar x = `/* new */`\n", false, false},
		{"build directive", "//go:build linux\n\npackage p\n", "//go:build darwin\n\npackage p\n", false, false},
		{"legacy build directive", "// +build linux\n\npackage p\n", "// +build darwin\n\npackage p\n", false, false},
		{"legacy build tab", "// +build\tlinux\n\npackage p\n", "// +build\tdarwin\n\npackage p\n", false, false},
		{"compiler directive", "package p\nfunc f() {}\n", "package p\n//go:noinline\nfunc f() {}\n", false, false},
		{"embed directive", "package p\n//go:embed a.txt\nvar s string\n", "package p\n//go:embed b.txt\nvar s string\n", false, false},
		{"line directive", "package p\n//line a.go:1\nvar x = 1\n", "package p\n//line b.go:1\nvar x = 1\n", false, false},
		{"block line directive", "package p\n/*line a.go:1*/var x = 1\n", "package p\n/*line b.go:1*/var x = 1\n", false, false},
		{"cgo preamble", "package p\n/* #define X 1 */\nimport \"C\"\n", "package p\n/* #define X 2 */\nimport \"C\"\n", false, false},
		{"cgo raw import", "package p\n/* #define X 1 */\nimport `C`\n", "package p\n/* #define X 2 */\nimport `C`\n", false, false},
		{"linter suppression", "package p\nvar x = 1 //nolint:errcheck\n", "package p\nvar x = 1\n", false, false},
		{"staticcheck suppression", "package p\n//lint:ignore SA1000 reason\nvar x = 1\n", "package p\nvar x = 1\n", false, false},
		{"generated marker", "// Code generated by x. DO NOT EDIT.\n\npackage p\n", "package p\n", false, false},
		{"example output", "package p\nfunc ExampleF() {\n\t// Output: 1\n}\n", "package p\nfunc ExampleF() {\n\t// Output: 2\n}\n", true, false},
		{"output comment outside tests", "package p\n// Output: 1\n", "package p\n// Output: 2\n", false, true},
		{"semicolon insertion", "package p\nfunc f() { return /* same line */ 1 }\n", "package p\nfunc f() { return /* new\nline */ 1 }\n", false, false},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			before, err := tokens([]byte(tt.before), tt.test)
			if err != nil {
				t.Fatal(err)
			}
			after, err := tokens([]byte(tt.after), tt.test)
			if err != nil {
				t.Fatal(err)
			}
			if equal := slices.Equal(before, after); equal != tt.equal {
				t.Fatalf("equal = %t, want %t", equal, tt.equal)
			}
		})
	}
}

func TestConstraints(t *testing.T) {
	src := "// Copyright\n\n//go:build linux\n// +build linux\n\npackage p\n\n//go:build ignored\n"
	if got := constraints([]byte(src)); !slices.Equal(got, []string{"//go:build linux", "// +build linux"}) {
		t.Fatalf("constraints = %q", got)
	}
}
